  <section className="lux-section lux-feature-section"><div className="lux-section-heading"><div><span className="lux-kicker dark-kicker">RESIDENTIAL PROPERTY</span><h2>Find a place to <em>call home.</em></h2><p>Explore residential plots and houses in DHA Lahore. Availability and asking prices must be confirmed.</p></div><Link className="lux-text-link" to="/properties">Browse residential <ArrowUpRight size={16}/></Link></div><div className="lux-property-grid">{residential.map((item,i)=><article className="lux-property-card" key={item.name}><div className="lux-property-photo"><img src={item.img} alt={item.type+' in '+item.phase+', DHA Lahore'}/><span>{item.type==='House'?'HOUSE':'RESIDENTIAL PLOT'}</span></div><div className="lux-property-info"><small><MapPin size={13}/>{item.phase}</small><h3>{item.name}</h3><div><span>{item.size}</span><b>Price on request</b></div><a href={wa('Please share current availability and details for '+item.name+' in '+item.phase+'.')}>Request details <ArrowUpRight size={15}/></a></div></article>)}</div></section>
