function FileRates(){const[phase,setPhase]=useState('All City/Phases'),[size,setSize]=useState('All sizes'),[type,setType]=useState('All types'),[query,setQuery]=useState('');const phasesList=[...new Set(rates.map(r=>r[0]))];const sizes=[...new Set(rates.map(r=>r[1]))];const visible=rates.filter(r=>(phase==='All City/Phases'||r[0]===phase)&&(size==='All sizes'||r[1]===size)&&(type==='All types'||r[2]===type)&&r.join(' ').toLowerCase().includes(query.toLowerCase()));const groups=phasesList.filter(p=>visible.some(r=>r[0]===p));return <><PageIntro eyebrow="DHA FILE RATES TODAY · UPDATED 29 OCTOBER 2026" title={<>DHA File Rates <em>Today.</em></>} desc="Check DHA File Rates Today with phase-wise property prices, residential and commercial file rates, affidavit and allocation prices, and the latest available market-rate information."/><section className="section rates-dashboard"><div className="rates-toolbar"><label className="rate-search"><span>⌕</span><input aria-label="Search phase, size or type" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search phase / size / type"/></label><label className="rate-select"><span>PHASE</span><select value={phase} onChange={e=>setPhase(e.target.value)}>{['All City/Phases',...phasesList].map(x=><option key={x}>{x}</option>)}</select></label><div className="rate-date"><span>UPDATED</span><b>29 Oct 2026</b></div><label className="rate-select"><span>SIZE</span><select value={size} onChange={e=>setSize(e.target.value)}>{['All sizes',...sizes].map(x=><option key={x}>{x}</option>)}</select></label><label className="rate-select"><span>TYPE</span><select value={type} onChange={e=>setType(e.target.value)}>{['All types','Residential','Commercial'].map(x=><option key={x}>{x}</option>)}</select></label><button className="btn outline" onClick={()=>{setPhase('All City/Phases');setSize('All sizes');setType('All types');setQuery('')}}>Reset filters</button></div><div className="rates-summary"><div><span className="eyebrow">MARKET REFERENCE</span><h2>DHA File Rates <em>Today</em></h2><p>Compare supplied rates by phase, size, property type and file category.</p></div><div className="rates-total"><b>{visible.length}</b><span>matching rate entries</span></div></div>{groups.length?groups.map(group=><section className="rate-phase-section" key={group}><div className="rate-phase-heading"><div><span className="eyebrow">CURRENT RATE REFERENCE</span><h3>{group}</h3></div><span className="rate-phase-count">{visible.filter(r=>r[0]===group).length} rates</span></div><div className="table-wrap rate-table-wrap"><table className="rate-table"><thead><tr><th>SIZE</th><th>TYPE</th><th>FILE CATEGORY</th><th>PRICE</th><th>PRICE (PKR)</th><th>TREND</th></tr></thead><tbody>{visible.filter(r=>r[0]===group).map((r,i)=><tr key={group+i}><td><b>{r[1]}</b></td><td>{r[2]}</td><td><span className="category-chip">{r[3]}</span></td><td className="rate-value">{r[4]}</td><td className="rate-numeric">{r[5]}</td><td><span className="trend-neutral">—</span></td></tr>)}</tbody></table></div></section>):<div className="rates-empty">No rates match these filters. Try another phase, size or search term.</div>}<div className="notice"><ShieldCheck/><p><b>Rate disclaimer:</b> These figures are supplied market references marked 29 October 2026. They are not independently verified live quotes or guaranteed transaction prices. Rates can change with demand, availability, file status and DHA requirements. Confirm the latest rate, original documentation, dues, transfer eligibility, taxes and duties before paying a token or making a commitment.</p></div></section><section className="section rates-guide"><div className="eyebrow">DHA FILE RATE GUIDE · OCTOBER 2026</div><h2>Understanding DHA File Rates <em>Today.</em></h2><p>When comparing DHA file rates today, review the phase, plot size, property type, file category, documentation and total transfer cost together. Compare like-for-like files and reconfirm the final quote before making a payment.</p><div className="rates-info-grid"><article><span>📊</span><h3>Compare similar files</h3><p>Compare the same phase, size and category. Differences in location, possession, documentation or status can affect a quote.</p></article><article><span>🧮</span><h3>Plan transfer expenses</h3><p>Budget for applicable transfer fees, taxes, duties and outstanding dues in addition to the quoted file price.</p><Link className="inline-link" to="/transfer-expense">Review transfer expenses <ArrowUpRight size={15}/></Link></article><article><span>📄</span><h3>Allocation vs affidavit</h3><p>Verify the original file category, current status and transfer conditions instead of assuming categories are interchangeable.</p><Link className="inline-link" to="/affidavit-vs-allocation">Compare file categories <ArrowUpRight size={15}/></Link></article><article><span>💡</span><h3>Why rates change</h3><p>Demand, development progress, balloting, availability and buyer activity can affect asking prices. Treat rates as time-sensitive references.</p></article></div><div className="rates-guidance-cta"><div><h3>Need help checking a DHA file?</h3><p>Ask us which details to verify before making a property decision in DHA Lahore.</p></div><a className="btn dark" href={wa('Please help me verify a DHA file rate and its documentation.')}>Discuss on WhatsApp <ArrowUpRight size={15}/></a></div></section></>}
